    if(b==0){
        x=1;
        y=0;
        return a;
    }
    LL x1,y1,d;
    d = exgcd(b,a%b,x1,y1);//为什么要d,因为最后通项要gcd(a,b)
    x=y1;y=x1-a/b*y1;
