LL get_phi(LL x){
    LL ret = x;
    for(int i=2;i<=x/i;i++){
        if(x%i==0){
            ret=ret/i*(i-1);//欧拉公式的定理
            while(x%i==0) x/=i;
        }
    }
    if(x>1) ret=ret/x*(x-1);
