void pushup(int p){
    tr[p].sum=tr[lc].sum+tr[rc].sum;
}

void build(int p,int l,int r){
    tr[p]={l,r,a[l]};//或者0
    if(l==r)return;

    int mid=(l+r)>>1;
    build(lc,l,mid);
    build(rc,mid+1,r);
    pushup(p);
}

void modify(int p,int x,int k){
    int l=tr[p].l,r=tr[p].r;
    if(x==l && r==x){
        tr[p].sum+=k;
        return;
    }

