//https://www.luogu.com.cn/problem/UVA529
#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
typedef pair<LL,LL> PLL;
typedef pair<int,int> PII;

#define qp '\n'

const LL N = 2e5 + 5;
const LL LINF = 0x3f3f3f3f3f3f3f3f;
const int INF = 0x3f3f3f3f;

int n;
int path[N];

bool dfs(int pos,int depth){
    if(pos>depth) return path[pos-1] == n;

    for(int i=0;i<pos;i++){
        for(int j=i;j<pos;j++){
            int x = path[i] + path[j];

            //当前剪枝
            if(x <= path[pos-1])continue;
            if(x>n)break;
            //预测剪枝
            if(x+depth-pos>n)break;
            if(x*(1<<(depth-pos))<n)continue;

            path[pos] = x;
            if(dfs(pos+1,depth)) return true;
        }
    }

    return false;
}

int main(){
    path[0] = 1;
    while(cin>>n,n){
        for(int depth=0;;depth++){
            if(dfs(1,depth)){
                //因为是UVA
                cout<<1;
                for(int i=1;i<=depth;i++){
                    cout<<' '<<path[i];
                }
                cout<<qp;
                break;
            }
        }
    }
}

#include<bits/stdc++.h>
using namespace std;

const int N=105;
const double EPS=1e-7;

double a[N][N];
int n;

inline bool zero(double x){
    return fabs(x)<EPS;
}

int gauss(){
    for(int i=1;i<=n;i++){
        int aim=i;
        for(int j=1;j<=n;j++){
            if(j<i && !zero(a[j][j])){
                continue;
            }
            if(fabs(a[j][i])>fabs(a[aim][i])){
                aim=j;
            }
        }

        if(zero(a[aim][i]))continue;

        for(int j=1;j<=n+1;j++)swap(a[aim][j],a[i][j]);

        for(int j=n+1;j>=i;j--)a[i][j]/=a[i][i];

        for(int j=1;j<=n;j++){
            if(i==j)continue;
            double t=a[j][i]/a[i][i];
            for(int k=i;k<=n+1;k++){
                a[j][k]-=a[i][k]*t;
            }
        }
    }

    int ret=1;
    for(int i=1;i<=n;i++){
        if(zero(a[i][i]) && !zero(a[i][n+1])){
            ret=0;
            return 0;
        }
        if(zero(a[i][i]))ret=2;
    }
    return ret;
}

int main(){
    cin>>n;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=n+1;j++){
            cin>>a[i][j];
        }
    }

    int ret = gauss();

    if(ret == 0|| ret == 2){
        cout<<"No Solution";
        return 0;
    }
    else{
        for(int i=1;i<=n;i++){
            printf("%.2lf\n",a[i][n+1]);
        }
        return 0;
    }
}

#include<bits/stdc++.h>
