int la,lb,lc;
int pos;

void mul(int a[],int b[],int c[]){
    for(int i=0;i<la;i++){
        for(int j=0;j<lb;j++){
            c[j+i]+=a[i]*b[j];
        }
    }
    for(int i=0;i<lc;i++){
        c[i+1] += c[i]/10;
        c[i] %= 10;
    }
    while(pos-1>0 && c[pos-1] == 0)pos--;
}

