    for(int i=0;i<la;i++)a[la-1-i]=x[i]-'0';
    for(int i=0;i<lb;i++)b[lb-1-i]=y[i]-'0';

    mul(a,b,c);

    for(int i=pos-1;i>=0;i--)cout<<c[i];
}

