    LL t=0;
    for(int i=lc-1;i>=0;i--){
        t = t*10+a[i];    //余数是=不是+= 不然会多加一次
        c[i] = t/b;
        t %= b;
    }
    while(lc-1>0 && c[lc-1]==0)lc--;
}

