const int MAXN=1e6+10;

int a[MAXN],b[MAXN],c[MAXN]={0};
string s1,s2;
int l1,l2,l3;

void ADD(int c[],int a[],int b[]){
    for(int i=0;i<l3;i++){
        c[i]+=a[i]+b[i];
        c[i+1]+=c[i]/10;
        c[i]%=10;
    }
    if(c[l3])l3++;
}

int main(){
