        a[l1-1-i]=s1[i]-'0';
    }
    for(int i=0;i<=l2-1;i++){
        b[l2-1-i]=s2[i]-'0';
    }
    ADD(c,a,b);
    for(int i=l3-1;i>=0;i--)cout<<c[i];
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

const int N=1e6+10;

int a[N]={0},b[N]={0},c[N]={0};
int la,lb,lc;
string x,y;

int main(){
    cin>>x>>y;
    la=x.size();//比较之前先定义
    lb=y.size();
    lc=max(la,lb);
    if(la != lb){
        if(la<lb){
            swap(x,y);
            cout<<'-';
        }
    }
    else{
        if(x<y){
            swap(x,y);
            cout<<'-';
        }
    }
    la=x.size();
    lb=y.size();//更新两个长度
    for(int i=0;i<la;i++)a[la-1-i]=x[i]-'0';//'0'不要忘
    for(int i=0;i<lb;i++)b[lb-1-i]=y[i]-'0';

